import { useState } from "react";
import { useApp } from "../../context/AppContext";
import { Pill } from "../../components/UI";

const menu = [
  { key: "ozet",       icon: "▦",  label: "Özet" },
  { key: "ilanlar",    icon: "📢", label: "İlanlar" },
  { key: "seferler",   icon: "✈️", label: "Seferler" },
  { key: "kullanicilar",icon: "👥",label: "Kullanıcılar" },
  { key: "gelir",      icon: "💰", label: "Gelir" },
  { key: "ayarlar",    icon: "⚙️", label: "Ayarlar" },
];

export default function AdminPanel() {
  const { ilanlar, seferler, kullanicilar, ilanSil, odemeYap, cikisYap } = useApp();
  const [aktif, setAktif] = useState("ozet");
  const [mobilMenu, setMobilMenu] = useState(false);

  const thStyle = { padding: "9px 12px", textAlign: "left", color: "var(--text3)", fontWeight: 600, fontSize: 10, letterSpacing: 0.5, textTransform: "uppercase", borderBottom: "1px solid var(--border)", background: "var(--bg2)", whiteSpace: "nowrap" };
  const tdStyle = { padding: "10px 12px", borderBottom: "1px solid var(--border)", color: "var(--text)", fontSize: 12, verticalAlign: "middle" };
  const btnStyle = { fontSize: 11, padding: "3px 10px", borderRadius: 6, cursor: "pointer", marginRight: 4 };

  const Sekme = () => {
    switch(aktif) {
      case "ozet": return (
        <div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 10, marginBottom: 20 }}>
            {[
              { val: ilanlar.filter(i=>i.durum==="aktif").length, lbl: "Aktif İlan", renk: "var(--yesil)", icon: "📢" },
              { val: seferler.filter(s=>s.durum==="yolda"||s.durum==="teslima_bekleniyor").length, lbl: "Aktif Sefer", renk: "var(--mavi)", icon: "✈️" },
              { val: kullanicilar.length, lbl: "Toplam Kullanıcı", renk: "var(--mavi)", icon: "👥" },
              { val: "₺142K", lbl: "Bu Ay Ciro", renk: "var(--turuncu)", icon: "💰" },
            ].map(s => (
              <div key={s.lbl} style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 16 }}>
                <div style={{ fontSize: 22, marginBottom: 4 }}>{s.icon}</div>
                <div style={{ fontFamily: "var(--font-d)", fontSize: 28, color: s.renk }}>{s.val}</div>
                <div style={{ fontSize: 11, color: "var(--text3)", marginTop: 2 }}>{s.lbl}</div>
              </div>
            ))}
          </div>
          <div style={{ fontFamily: "var(--font-d)", fontSize: 15, letterSpacing: 1, color: "var(--text3)", marginBottom: 10 }}>AKTİF SEFERLER</div>
          <div style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", overflow: "auto" }}>
            <table className="tbl">
              <thead><tr><th style={thStyle}>Yük</th><th style={thStyle}>Güzergah</th><th style={thStyle}>Kamyoncu</th><th style={thStyle}>Durum</th></tr></thead>
              <tbody>{seferler.filter(s=>s.durum==="yolda"||s.durum==="teslima_bekleniyor").slice(0,4).map(s => (
                <tr key={s.id}>
                  <td style={tdStyle}>{s.yuk}</td>
                  <td style={tdStyle}>{s.nereden}→{s.nereye}</td>
                  <td style={tdStyle}>{s.kamyoncu} • {s.plaka}</td>
                  <td style={tdStyle}><Pill durum={s.durum}/></td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        </div>
      );

      case "ilanlar": return (
        <div style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", overflow: "auto" }}>
          <table className="tbl">
            <thead><tr><th style={thStyle}>Yük</th><th style={thStyle}>Güzergah</th><th style={thStyle}>Ücret</th><th style={thStyle}>İstek</th><th style={thStyle}>Durum</th><th style={thStyle}>İşlem</th></tr></thead>
            <tbody>{ilanlar.filter(i => i.durum === "aktif").map(i => (
              <tr key={i.id}>
                <td style={tdStyle}>{i.yuk}</td>
                <td style={tdStyle}>{i.nereden}→{i.nereye}</td>
                <td style={{...tdStyle,color:"var(--sari)",fontWeight:600}}>₺{i.ucret.toLocaleString()}</td>
                <td style={tdStyle}>{i.istekSayisi}</td>
                <td style={tdStyle}><Pill durum={i.durum}/></td>
                <td style={tdStyle}>
                  <button onClick={()=>ilanSil(i.id)} style={{...btnStyle,border:"1px solid rgba(239,68,68,0.4)",background:"none",color:"var(--kirmizi)"}}>Kaldır</button>
                </td>
              </tr>
            ))}</tbody>
          </table>
        </div>
      );

      case "teklifler": return (
        <div style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", overflow: "auto" }}>
          <table className="tbl">
            <thead><tr><th style={thStyle}>Kamyoncu</th><th style={thStyle}>Plaka</th><th style={thStyle}>Yük</th><th style={thStyle}>Güzergah</th><th style={thStyle}>Durum</th></tr></thead>
            <tbody>{seferler.map(s => (
              <tr key={s.id}>
                <td style={tdStyle}>{s.kamyoncu}</td>
                <td style={tdStyle}>{s.plaka}</td>
                <td style={tdStyle}>{s.yuk}</td>
                <td style={tdStyle}>{s.nereden}→{s.nereye}</td>
                <td style={tdStyle}><Pill durum={s.durum}/></td>
              </tr>
            ))}</tbody>
          </table>
        </div>
      );

      case "seferler": return (
        <div style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", overflow: "auto" }}>
          <table className="tbl">
            <thead><tr><th style={thStyle}>Yük</th><th style={thStyle}>Güzergah</th><th style={thStyle}>Kamyoncu</th><th style={thStyle}>Plaka</th><th style={thStyle}>Teslim Tarihi</th><th style={thStyle}>Durum</th></tr></thead>
            <tbody>{seferler.map(s => (
              <tr key={s.id}>
                <td style={tdStyle}>{s.yuk}</td>
                <td style={tdStyle}>{s.nereden}→{s.nereye}</td>
                <td style={tdStyle}>{s.kamyoncu}</td>
                <td style={tdStyle}>{s.plaka}</td>
                <td style={tdStyle}>{s.teslimTarihi || "-"}</td>
                <td style={tdStyle}><Pill durum={s.durum}/></td>
              </tr>
            ))}</tbody>
          </table>
        </div>
      );

      case "kullanicilar": return (
        <div style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", overflow: "auto" }}>
          <table className="tbl">
            <thead><tr><th style={thStyle}>Ad</th><th style={thStyle}>Rol</th><th style={thStyle}>Puan</th><th style={thStyle}>Aktif Sefer</th><th style={thStyle}>Durum</th><th style={thStyle}>İşlem</th></tr></thead>
            <tbody>{kullanicilar.map(k => {
              const seferlerim = seferler.filter(s => s.kamyoncu === k.ad);
              const aktifSeferler = seferlerim.filter(s => s.durum === "yolda" || s.durum === "teslima_bekleniyor");
              return (
              <tr key={k.id}>
                <td style={tdStyle}>{k.ad}</td>
                <td style={tdStyle}><Pill durum={k.rol==="kamyoncu"?"aktif":"bekliyor"}/> <span style={{fontSize:11,color:"var(--text3)"}}>{k.rol}</span></td>
                <td style={{...tdStyle,color:"var(--sari)"}}>⭐ {k.puan}</td>
                <td style={tdStyle}>{aktifSeferler.length}</td>
                <td style={tdStyle}><Pill durum={k.durum}/></td>
                <td style={tdStyle}>
                  <button style={{...btnStyle,border:"1px solid var(--border2)",background:"none",color:"var(--text2)"}}>Profil</button>
                  <button style={{...btnStyle,border:"1px solid rgba(245,166,35,0.4)",background:"none",color:"var(--sari)"}}>Askı</button>
                </td>
              </tr>
            )})}</tbody>
          </table>
        </div>
      );

      case "gelir": return (
        <div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
            {[
              { lbl: "Bu Ay Komisyon", val: "₺14.280", renk: "var(--yesil)" },
              { lbl: "Bu Ay Abonelik", val: "₺8.970", renk: "var(--mavi)" },
              { lbl: "Toplam Ciro", val: "₺142K", renk: "var(--sari)" },
              { lbl: "Bekleyen Ödeme", val: "₺3.200", renk: "var(--turuncu)" },
            ].map(s => (
              <div key={s.lbl} style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r)", padding: 14 }}>
                <div style={{ fontSize: 11, color: "var(--text3)", marginBottom: 4 }}>{s.lbl}</div>
                <div style={{ fontFamily: "var(--font-d)", fontSize: 24, color: s.renk }}>{s.val}</div>
              </div>
            ))}
          </div>
          <div style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", overflow: "auto" }}>
            <table className="tbl">
              <thead><tr><th style={thStyle}>Tarih</th><th style={thStyle}>İşlem</th><th style={thStyle}>Komisyon</th><th style={thStyle}>Abonelik</th><th style={thStyle}>Durum</th></tr></thead>
              <tbody>
                {[
                  { tarih:"03 May", islem:"İstanbul→Gaziantep", kom:"₺525", ab:"—", d:"onaylandı" },
                  { tarih:"02 May", islem:"Pro Üyelik - Mehmet Y.", kom:"—", ab:"₺299", d:"onaylandı" },
                  { tarih:"01 May", islem:"Antalya→İzmir", kom:"₺410", ab:"—", d:"bekliyor" },
                  { tarih:"30 Nis", islem:"Pro Üyelik - Ali K.", kom:"—", ab:"₺299", d:"onaylandı" },
                ].map((r,i)=>(
                  <tr key={i}>
                    <td style={tdStyle}>{r.tarih}</td>
                    <td style={tdStyle}>{r.islem}</td>
                    <td style={{...tdStyle,color:"var(--yesil)"}}>{r.kom}</td>
                    <td style={{...tdStyle,color:"var(--mavi)"}}>{r.ab}</td>
                    <td style={tdStyle}><Pill durum={r.d}/></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      );

      case "ayarlar": return (
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {[
            { baslik: "Uygulama", alanlar: [{ lbl: "Uygulama Adı", val: "NakliYol" }, { lbl: "Destek E-posta", val: "info@nakliyol.com" }, { lbl: "Versiyon", val: "2.0.0" }] },
            { baslik: "Komisyon", alanlar: [{ lbl: "Komisyon Oranı", val: "%3" }, { lbl: "Pro Üyelik (Aylık)", val: "₺299" }, { lbl: "Kurumsal Üyelik", val: "₺699" }] },
          ].map(grup => (
            <div key={grup.baslik} style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 16 }}>
              <div className="label" style={{ marginBottom: 14 }}>{grup.baslik}</div>
              {grup.alanlar.map(a => (
                <div key={a.lbl} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "9px 0", borderBottom: "1px solid var(--border)" }}>
                  <span style={{ fontSize: 13 }}>{a.lbl}</span>
                  <div style={{ display: "flex", gap: 6 }}>
                    <input defaultValue={a.val} style={{ width: 120, background: "var(--bg2)", border: "1px solid var(--border2)", borderRadius: 6, padding: "4px 8px", color: "var(--text)", fontSize: 12 }} />
                    <button style={{ fontSize: 11, padding: "4px 10px", borderRadius: 6, border: "1px solid var(--border2)", background: "none", color: "var(--text2)", cursor: "pointer" }}>Kaydet</button>
                  </div>
                </div>
              ))}
            </div>
          ))}
          <div style={{ background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r-lg)", padding: 16 }}>
            <div className="label" style={{ marginBottom: 14 }}>Özellikler</div>
            {[["SMS Bildirimleri","on"],["E-posta Bildirimleri","on"],["Belge Zorunluluğu","off"],["Bakım Modu","off"]].map(([lbl,d])=>{
              const [on, setOn] = useState(d==="on");
              return <div key={lbl} className="toggle-wrap"><span className="toggle-label">{lbl}</span><button className={`toggle ${on?"on":""}`} onClick={()=>setOn(x=>!x)}/></div>;
            })}
          </div>
        </div>
      );

      default: return null;
    }
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", background: "var(--bg)" }}>
      {/* Sidebar */}
      <div style={{ width: 200, background: "var(--bg1)", borderRight: "1px solid var(--border)", padding: "0", flexShrink: 0, display: "flex", flexDirection: "column", position: "sticky", top: 0, height: "100vh" }}>
        <div style={{ padding: "18px 16px 16px", borderBottom: "1px solid var(--border)" }}>
          <div className="logo" style={{ fontSize: 22 }}>NAKLI<span className="logo-accent">YOL</span></div>
          <div className="label" style={{ marginTop: 2 }}>Admin Paneli</div>
        </div>
        <div style={{ flex: 1, padding: "8px 0" }}>
          {menu.map(m => (
            <button key={m.key} onClick={() => setAktif(m.key)} style={{
              width: "100%", display: "flex", alignItems: "center", gap: 10,
              padding: "10px 16px", background: "none", border: "none",
              color: aktif === m.key ? "var(--sari)" : "var(--text3)",
              borderRight: aktif === m.key ? "2px solid var(--turuncu)" : "2px solid transparent",
              fontSize: 13, fontWeight: aktif === m.key ? 600 : 400,
              cursor: "pointer", textAlign: "left", transition: "var(--tr)",
            }}>
              <span>{m.icon}</span> {m.label}
            </button>
          ))}
        </div>
        <div style={{ padding: 16, borderTop: "1px solid var(--border)" }}>
          <button onClick={cikisYap} style={{ width: "100%", background: "none", border: "1px solid var(--border)", borderRadius: "var(--r)", padding: "8px", color: "var(--text3)", fontSize: 12, cursor: "pointer" }}>← Çıkış</button>
        </div>
      </div>

      {/* Main content */}
      <div style={{ flex: 1, overflow: "auto" }}>
        <div style={{ padding: "14px 20px", borderBottom: "1px solid var(--border)", display: "flex", justifyContent: "space-between", alignItems: "center", position: "sticky", top: 0, background: "rgba(10,10,10,0.92)", backdropFilter: "blur(12px)", zIndex: 10 }}>
          <div className="display" style={{ fontSize: 18, letterSpacing: 1 }}>{menu.find(m=>m.key===aktif)?.label?.toUpperCase()}</div>
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <span className="pill pill-amber">{seferler.filter(s=>s.durum==="teslima_bekleniyor").length} teslim bekliyor</span>
            <div style={{ width: 28, height: 28, borderRadius: "50%", background: "var(--bg3)", display: "flex", alignItems: "center", justifyContent: "center" }}>⚙️</div>
          </div>
        </div>
        <div style={{ padding: 20 }}><Sekme /></div>
      </div>
    </div>
  );
}
